function captureCollectionEditor(){const c=currentCollection();if(!c||$('collectionEditorView')?.hidden)return;captureTranslationFields(c,'collection');c.title=$('collectionTitle').value.trim()||'Untitled collection';c.description=$('collectionDescription').value;c.handle=slugify($('collectionHandle').value||c.title);c.status=$('collectionStatus').value;c.productIds=[...$('collectionProductChecks').querySelectorAll('input:checked')].map(x=>x.value);(adminState.catalogProducts||[]).forEach(p=>{p.collectionIds=p.collectionIds||[];p.collectionIds=p.collectionIds.filter(id=>id!==c.id);if(c.productIds.includes(p.id))p.collectionIds.push(c.id)})}
