function bundleScopeTargetOptions(b){if(b.scopeType==='all')return '<option value="">Entire store</option>';const list=b.scopeType==='collection'?adminState.collections:adminState.catalogProducts;return (list||[]).map(x=>`<option value="${x.id}" ${b.scopeId===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}
