function captureBundles(){document.querySelectorAll('[data-bundle]').forEach(el=>{const i=+el.dataset.bundle,b=adminState.bundles[i];if(!b)return;el.querySelectorAll('[data-bk]').forEach(inp=>{let v=inp.type==='checkbox'?inp.checked:inp.value;if(['qty','price'].includes(inp.dataset.bk))v=v===''?null:Number(v);b[inp.dataset.bk]=v});if(b.scopeType==='all')b.scopeId=''})}

function renderSettings(){
  $('editEyebrow').value=adminState.homepage.eyebrow||'';$('editTitle').value=adminState.homepage.title||'';$('editSubtitle').value=adminState.homepage.subtitle||'';
  $('subscriptionStorefrontVisible').checked=adminState.subscriptions.storefrontVisible!==false;$('subscriptionLabel').value=adminState.subscriptions.label||'Subscribe & save';$('subscriptionDiscount').value=Number(adminState.subscriptions.discount||0);
  $('bundlesStorefrontVisible').checked=adminState.features?.bundlesStorefrontVisible===true;$('customerAccountsEnabled').checked=adminState.features?.customerAccounts!==false;
  $('salesEmails').value=adminState.settings.salesEmails||adminState.settings.internalEmail||'';$('adminEmails').value=adminState.settings.adminEmails||'';$('sendSalesOrder').checked=adminState.settings.sendSalesOrder!==false;$('sendSalesReceipt').checked=adminState.settings.sendSalesReceipt!==false;$('receiptFromName').value=adminState.settings.receiptFromName||'ZB';$('receiptPrefix').value=adminState.settings.receiptPrefix||'ZB';const hkMarket=(adminState.markets?.items||[]).find(x=>x.id==='hk');$('shippingFee').value=hkMarket?.shippingFee??adminState.shipping.fee;$('freeShippingThreshold').value=hkMarket?.freeShippingThreshold??adminState.shipping.threshold;
  const f=adminState.footer||defaults.footer;$('footerTagline').value=f.tagline||'';$('socialInstagram').value=f.socials?.instagram||'';$('socialTiktok').value=f.socials?.tiktok||'';$('socialYoutube').value=f.socials?.youtube||'';$('socialFacebook').value=f.socials?.facebook||'';$('socialLinkedin').value=f.socials?.linkedin||'';
  const t=adminState.theme||defaults.theme;$('editFont').value=t.font||'Instrument Sans';$('editBodySize').value=String(t.bodySize||defaults.theme.bodySize||18);$('editBg').value=t.bg||defaults.theme.bg;$('editText').value=t.text||defaults.theme.text;$('editSurface').value=t.surface||defaults.theme.surface;$('editSoftSurface').value=t.softSurface||defaults.theme.softSurface;$('editSelectedFill').value=t.selectedFill||defaults.theme.selectedFill;$('editAccent').value=t.accent||defaults.theme.accent;$('editButton').value=t.button||defaults.theme.button;$('editButtonText').value=t.buttonText||defaults.theme.buttonText;$('editLine').value=t.line||defaults.theme.line;
  const b=adminState.branding||defaults.branding;$('navLogoUrl').value=b.logo||'';$('faviconUrl').value=b.favicon||'assets/favicon.svg';$('navLogoText').value=b.logoText||'ZIONBURG';$('mobileLogoText').value=b.mobileLogoText||'ZB';$('navLogoWidth').value=b.logoWidth||132;$('mobileLogoWidth').value=b.mobileLogoWidth||44;
  renderGenericEditors();renderHomeMediaEditors();renderBenefitEditors();renderBrandingPreviews();renderProductList();renderCollectionList();renderBundleEditors();renderLanguageSettings();renderMarketEditors();previewShipping();
}
function captureSettings(){
  adminState.homepage={eyebrow:$('editEyebrow').value,title:$('editTitle').value,subtitle:$('editSubtitle').value};adminState.subscriptions.enabled=true;adminState.subscriptions.storefrontVisible=$('subscriptionStorefrontVisible').checked;adminState.subscriptions.label=$('subscriptionLabel').value;adminState.subscriptions.discount=Number($('subscriptionDiscount').value||0);
  adminState.features={...(adminState.features||defaults.features),bundlesStorefrontVisible:$('bundlesStorefrontVisible').checked,customerAccounts:$('customerAccountsEnabled').checked};
  adminState.settings={...(adminState.settings||{}),internalEmail:$('salesEmails').value.split(/[;,\n]+/).map(x=>x.trim()).filter(Boolean)[0]||'',salesEmails:$('salesEmails').value,adminEmails:$('adminEmails').value,sendSalesOrder:$('sendSalesOrder').checked,sendSalesReceipt:$('sendSalesReceipt').checked,receiptFromName:$('receiptFromName').value,receiptPrefix:$('receiptPrefix').value};adminState.shipping={fee:Number($('shippingFee').value||0),threshold:Number($('freeShippingThreshold').value||0)};const hkMarket=(adminState.markets?.items||[]).find(x=>x.id==='hk');if(hkMarket){hkMarket.shippingFee=adminState.shipping.fee;hkMarket.freeShippingThreshold=adminState.shipping.threshold;}
  adminState.footer={...(adminState.footer||defaults.footer),tagline:$('footerTagline').value,socials:{instagram:$('socialInstagram').value.trim(),tiktok:$('socialTiktok').value.trim(),youtube:$('socialYoutube').value.trim(),facebook:$('socialFacebook').value.trim(),linkedin:$('socialLinkedin').value.trim()}};
  adminState.theme={font:$('editFont').value,bodySize:Number($('editBodySize').value||18),bg:$('editBg').value,text:$('editText').value,surface:$('editSurface').value,softSurface:$('editSoftSurface').value,selectedFill:$('editSelectedFill').value,accent:$('editAccent').value,button:$('editButton').value,buttonText:$('editButtonText').value,line:$('editLine').value};
  adminState.branding={...adminState.branding,logo:$('navLogoUrl').value.trim(),favicon:$('faviconUrl').value.trim()||'assets/favicon.svg',logoText:$('navLogoText').value.trim()||'ZIONBURG',mobileLogoText:$('mobileLogoText').value.trim()||'ZB',logoAlt:$('navLogoText').value.trim()||'ZIONBURG',logoWidth:Number($('navLogoWidth').value||132),mobileLogoWidth:Number($('mobileLogoWidth').value||44)};
}
function captureAll(){try{captureProductEditor();captureCollectionEditor();captureBundles();captureGenericEditors();captureFooterLinks();captureHomeMedia();captureBenefits();captureLanguageSettings();captureMarketEditors();captureSettings()}catch(e){console.warn('Admin capture skipped:',e)}}

function addGeneric(type,obj){captureAll();const map={page:'pages',nav:'nav',stockist:'stockists',partner:'partners',friend:'friends',discount:'discounts'};if(type==='subplan')adminState.subscriptions.plans.push(obj);else adminState[map[type]].push(obj);renderGenericEditors()}
function removeGeneric(type,i){captureAll();const map={page:'pages',nav:'nav',stockist:'stockists',partner:'partners',friend:'friends',discount:'discounts'};if(type==='subplan')adminState.subscriptions.plans.splice(i,1);else adminState[map[type]].splice(i,1);renderGenericEditors()}

function readAssetUpload(input,onDone){const file=input.files?.[0];if(!file)return;const video=file.type.startsWith('video/'),limit=video?1800000:900000;if(file.size>limit){alert(video?'For this static prototype, keep direct video uploads under 1.8 MB. Use an MP4/WebM URL or YouTube link for normal marketing videos.':'Please keep uploaded image/logo/icon files under 900 KB for this browser prototype.');input.value='';return}const r=new FileReader();r.onload=()=>onDone(String(r.result||''));r.readAsDataURL(file)}
function previewShipping(){$('shippingPreview').textContent=Number($('freeShippingThreshold').value||0)>0?`Storefront message: Free HK delivery over ${money($('freeShippingThreshold').value)}`:'Storefront message: Free HK delivery on every order'}

let invoiceLines=[{description:'Custom order',qty:1,price:0}];
function renderInvoiceLines(){$('invoiceLines').innerHTML=invoiceLines.map((l,i)=>`<div class="invoice-line" data-invoice-line="${i}"><input data-k="description" value="${esc(l.description)}" placeholder="Description"><input data-k="qty" type="number" min="1" value="${l.qty}"><input data-k="price" type="number" min="0" value="${l.price}" placeholder="Price"><button class="admin-secondary compact" data-remove-invoice-line="${i}">Remove</button></div>`).join('')}
function saveInvoice(){document.querySelectorAll('[data-invoice-line]').forEach(el=>{const i=+el.dataset.invoiceLine;el.querySelectorAll('[data-k]').forEach(inp=>invoiceLines[i][inp.dataset.k]=inp.type==='number'?Number(inp.value):inp.value)});const subtotal=invoiceLines.reduce((s,l)=>s+l.qty*l.price,0),shipping=Number($('invoiceShipping').value||0),discount=Number($('invoiceDiscount').value||0),total=Math.max(0,subtotal+shipping-discount);const inv={id:'INV-'+String(Date.now()).slice(-8),created:new Date().toISOString(),customer:$('invoiceCustomer').value,email:$('invoiceEmail').value,due:$('invoiceDue').value,reference:$('invoiceRef').value,notes:$('invoiceNotes').value,lines:invoiceLines,subtotal,shipping,discount,total,status:'Unpaid'};const arr=invoices();arr.unshift(inv);localStorage.setItem(ZB_INVOICES,JSON.stringify(arr));const url=new URL('invoice.html',location.href);url.searchParams.set('invoice',inv.id);if(inv.email)logEmailEvent({type:'Customer invoice',to:inv.email,subject:`ZIONBURG invoice ${inv.id}`,invoiceId:inv.id});salesEmailList(adminState).forEach(to=>logEmailEvent({type:'Sales invoice copy',to,subject:`Invoice copy — ${inv.id}`,invoiceId:inv.id}));fetch('/.netlify/functions/send-invoice-email',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({invoice:inv,url:url.href,event:'created'})}).catch(()=>{});$('invoiceSuccess').innerHTML=`Payment link created:<br><a href="${url.href}" target="_blank">${url.href}</a>`;$('invoiceSuccess').classList.add('show');renderInvoices();renderEmailLog()}
function renderInvoices(){const arr=invoices();$('invoiceTable').innerHTML=arr.map(i=>`<tr><td><strong>${esc(i.id)}</strong></td><td>${esc(i.customer||i.email||'—')}</td><td>${money(i.total)}</td><td>${statusBadge(i.status==='Paid'?'active':'draft')}</td><td><a class="text-button" href="invoice.html?invoice=${encodeURIComponent(i.id)}" target="_blank">Open</a></td></tr>`).join('')||'<tr><td colspan="5" class="empty-cell">No custom invoices yet.</td></tr>'}

function bindEvents(){
  $('saveAdmin').onclick=async()=>{captureAll();saveSite(adminState);const btn=$('saveAdmin'),old=btn.textContent;btn.disabled=true;btn.textContent='Publishing…';try{await ZBSupa.syncSite(adminState);adminState=getSite();renderSales();renderAnalytics();renderSubs();renderEmailLog();showSaveToast()}catch(err){console.error(err);alert('Could not publish to Supabase: '+err.message)}finally{btn.disabled=false;btn.textContent=old}};
  $('loadDemo').onclick=()=>{if(!confirm('Reset the prototype content to the ZB demo defaults?'))return;localStorage.removeItem(ZB_KEY);adminState=getSite();selectedProductId=null;selectedCollectionId=null;selectedInterfaceLocale=null;renderSettings();renderSales();renderAnalytics();renderSubs();renderEmailLog()};
  $('addProduct').onclick=addNewProduct;$('backProducts').onclick=()=>{captureProductEditor();renderProductList()};$('doneProduct').onclick=()=>{captureProductEditor();renderProductList()};
  $('duplicateProduct').onclick=()=>{captureProductEditor();const p=currentProduct();if(!p)return;const copy=JSON.parse(JSON.stringify(p));copy.id=uid('prod');copy.title=`${p.title} copy`;copy.handle=`${p.handle}-copy-${Date.now().toString().slice(-3)}`;copy.status='draft';copy.variants=(copy.variants||[]).map(v=>({...v,id:uid('var')}));adminState.catalogProducts.push(copy);(copy.collectionIds||[]).forEach(cid=>{const c=adminState.collections.find(x=>x.id===cid);if(c){c.productIds=c.productIds||[];c.productIds.push(copy.id)}});openProductEditor(copy.id)};
  $('archiveProduct').onclick=()=>{const p=currentProduct();if(!p)return;p.status=p.status==='archived'?'draft':'archived';$('productStatus').value=p.status;$('archiveProduct').textContent=p.status==='archived'?'Unarchive':'Archive'};
  $('addVariant').onclick=()=>{captureProductEditor();const p=currentProduct();p.variants.push({id:uid('var'),name:'New variant',state:'',price:0,sku:'',color:'#d8d8d8',image:'',inventory:0,active:true});renderVariantEditors()};
  $('addProductMedia').onclick=()=>{captureProductEditor();const p=currentProduct();p.media.push({type:'image',src:'',poster:'',alt:'',autoplay:true,loop:true,controls:false});renderProductMediaEditors()};
  $('addCollection').onclick=addNewCollection;$('backCollections').onclick=()=>{captureCollectionEditor();renderCollectionList()};$('doneCollection').onclick=()=>{captureCollectionEditor();renderCollectionList()};$('deleteCollection').onclick=()=>{const c=currentCollection();if(!c||!confirm(`Delete “${c.title}”?`))return;adminState.collections=adminState.collections.filter(x=>x.id!==c.id);adminState.catalogProducts.forEach(p=>p.collectionIds=(p.collectionIds||[]).filter(id=>id!==c.id));adminState.bundles=adminState.bundles.filter(b=>!(b.scopeType==='collection'&&b.scopeId===c.id));renderCollectionList()};
  $('addMarket').onclick=()=>{captureAll();adminState.markets.items.push({id:uid('market'),name:'New market',countries:['Other'],currency:'USD',symbol:'US$',fxRate:0.128,enabled:false,taxRate:0,shippingFee:0,freeShippingThreshold:0,deliveryEstimate:'5–12 business days'});renderMarketEditors()};
  $('addBundle').onclick=()=>{captureAll();const p=adminState.catalogProducts[0];adminState.bundles.push({id:uid('bundle'),name:'New bundle',qty:3,price:null,badge:'',active:true,scopeType:p?'product':'all',scopeId:p?.id||''});renderBundleEditors()};
  $('addDiscount').onclick=()=>addGeneric('discount',{code:'NEWCODE',type:'percent',value:10,enabled:true});$('addSubPlan').onclick=()=>addGeneric('subplan',{label:'Every 4 weeks',value:'4-weeks'});$('addPage').onclick=()=>addGeneric('page',{title:'New Page',slug:'new-page',body:'Add page content here.'});$('addNav').onclick=()=>addGeneric('nav',{label:'New Link',type:'link',href:'page.html?slug=new-page',visible:true});$('addStockist').onclick=()=>addGeneric('stockist',{name:'New stockist',type:'Physical Store',country:'Hong Kong',region:'',city:'',address:'',url:'',active:true});$('addFooterLink').onclick=()=>{captureAll();adminState.footer=adminState.footer||clone(defaults.footer);adminState.footer.links=adminState.footer.links||[];adminState.footer.links.push({label:'New link',href:'',visible:true});renderFooterLinkEditors()};$('addPartner').onclick=()=>addGeneric('partner',{name:'New partner',type:'Community partner',note:'',image:'',imageFit:'cover',url:''});$('addFriend').onclick=()=>addGeneric('friend',{name:'New friend',type:'Creator',note:'',image:'',imageFit:'cover',url:''});
  $('resetBenefitIcons').onclick=()=>{captureBenefits();const icons=['assets/plant.svg','assets/alcohol-free.svg','assets/vitamin.svg','assets/cooling.svg'];adminState.benefits.forEach((b,i)=>b.icon=icons[i]||b.icon);renderBenefitEditors()};
  $('resetNavLogo').onclick=()=>{adminState.branding.logo='';$('navLogoUrl').value='';renderBrandingPreviews()};$('resetFavicon').onclick=()=>{adminState.branding.favicon='assets/favicon.svg';$('faviconUrl').value='assets/favicon.svg';renderBrandingPreviews()};
  $('freeShippingThreshold').addEventListener('input',previewShipping);$('productSearch').addEventListener('input',renderProductList);$('productStatusFilter').addEventListener('change',renderProductList);
  $('productTitle').addEventListener('input',()=>{if(!$('productHandle').dataset.touched)$('productHandle').value=slugify($('productTitle').value)});$('productHandle').addEventListener('input',()=>$('productHandle').dataset.touched='1');$('collectionTitle').addEventListener('input',()=>{if(!$('collectionHandle').dataset.touched)$('collectionHandle').value=slugify($('collectionTitle').value)});$('collectionHandle').addEventListener('input',()=>$('collectionHandle').dataset.touched='1');
  $('addInvoiceLine').onclick=()=>{invoiceLines.push({description:'',qty:1,price:0});renderInvoiceLines()};$('generateInvoice').onclick=saveInvoice;
  $('shipmentForm').addEventListener('submit',e=>{e.preventDefault();saveShipment()});$('closeShipmentDialog').onclick=closeShipmentDialog;$('cancelShipmentDialog').onclick=closeShipmentDialog;$('shipmentDialog').addEventListener('click',e=>{if(e.target===$('shipmentDialog'))closeShipmentDialog()});

  document.addEventListener('click',e=>{
    const ep=e.target.closest('[data-edit-product]');if(ep){openProductEditor(ep.dataset.editProduct);return}const ec=e.target.closest('[data-edit-collection]');if(ec){openCollectionEditor(ec.dataset.editCollection);return}
    const rv=e.target.closest('[data-remove-variant]');if(rv){captureVariants();const p=currentProduct();p.variants.splice(+rv.dataset.removeVariant,1);renderVariantEditors();return}
    const rm=e.target.closest('[data-remove-product-media]');if(rm){captureProductMedia();const p=currentProduct();p.media.splice(+rm.dataset.removeProductMedia,1);renderProductMediaEditors();return}
    const mv=e.target.closest('[data-move-product-media]');if(mv){captureProductMedia();const p=currentProduct(),i=+mv.dataset.mediaOrderIndex,j=mv.dataset.moveProductMedia==='up'?i-1:i+1;if(j>=0&&j<p.media.length){[p.media[i],p.media[j]]=[p.media[j],p.media[i]];renderProductMediaEditors()}return}
    const rmk=e.target.closest('[data-remove-market]');if(rmk){captureMarketEditors();const i=+rmk.dataset.removeMarket;if(adminState.markets.items[i]?.id!=='hk'){adminState.markets.items.splice(i,1);renderMarketEditors()}return}
    const rb=e.target.closest('[data-remove-bundle]');if(rb){captureBundles();adminState.bundles.splice(+rb.dataset.removeBundle,1);renderBundleEditors();return}
    const rfl=e.target.closest('[data-remove-footer-link]');if(rfl){captureFooterLinks();adminState.footer.links.splice(+rfl.dataset.removeFooterLink,1);renderFooterLinkEditors();return}
    const rg=e.target.closest('[data-remove]');if(rg){const type=rg.dataset.remove,el=rg.closest(`[data-${type}]`);removeGeneric(type,+el.dataset[type]);return}
    const ril=e.target.closest('[data-remove-invoice-line]');if(ril){invoiceLines.splice(+ril.dataset.removeInvoiceLine,1);renderInvoiceLines();return}
    const sh=e.target.closest('[data-ship-order]');if(sh){openShipmentDialog(+sh.dataset.shipOrder);return}
  });
  document.addEventListener('change',e=>{
    if(e.target.id==='interfaceTranslationLocale'){captureInterfaceTranslations(selectedInterfaceLocale);selectedInterfaceLocale=e.target.value;renderInterfaceTranslationEditor();return}
    const cu=e.target.closest('[data-community-upload]');if(cu){const type=cu.dataset.communityUpload,i=+cu.dataset.communityIndex;readAssetUpload(cu,data=>{captureGenericEditors();const key=type==='partner'?'partners':'friends';if(adminState[key]?.[i])adminState[key][i].image=data;renderGenericEditors()});return}
    if(e.target.matches('[data-language-index],#defaultLocale')){captureLanguageSettings();renderLanguageSettings();const p=currentProduct();if(p&&$('productTranslationEditors'))$('productTranslationEditors').innerHTML=translationFieldsHTML(p,'product');const c=currentCollection();if(c&&$('collectionTranslationEditors'))$('collectionTranslationEditors').innerHTML=translationFieldsHTML(c,'collection');return}
    const scope=e.target.closest('[data-bk="scopeType"]');if(scope){captureBundles();const b=scope.closest('[data-bundle]'),obj=adminState.bundles[+b.dataset.bundle];obj.scopeType=scope.value;obj.scopeId=scope.value==='product'?adminState.catalogProducts[0]?.id||'':scope.value==='collection'?adminState.collections[0]?.id||'':'';renderBundleEditors();return}
    const bu=e.target.closest('[data-benefit-upload]');if(bu){const i=+bu.dataset.benefitUpload;readAssetUpload(bu,data=>{captureBenefits();adminState.benefits[i].icon=data;renderBenefitEditors()});return}
    const mu=e.target.closest('[data-media-upload-scope]');if(mu){const scopeName=mu.dataset.mediaUploadScope,i=+mu.dataset.mediaUploadIndex;readAssetUpload(mu,data=>{if(scopeName==='home'){captureHomeMedia();const arr=homeMediaFlat();arr[i].src=data;arr[i].type=mu.files?.[0]?.type.startsWith('video/')?'video':'image';setHomeMediaFlat(arr);renderHomeMediaEditors()}else{captureProductMedia();const p=currentProduct();p.media[i].src=data;p.media[i].type=mu.files?.[0]?.type.startsWith('video/')?'video':'image';renderProductMediaEditors()}});return}
    if(e.target.closest('[data-media-k]')){if(e.target.closest('[data-media-scope="home"]')){captureHomeMedia();renderHomeMediaEditors()}else if(e.target.closest('[data-media-scope="product"]')){captureProductMedia();renderProductMediaEditors()}}
  });
  $('navLogoFile').addEventListener('change',e=>readAssetUpload(e.target,data=>{adminState.branding.logo=data;$('navLogoUrl').value=data;renderBrandingPreviews()}));$('faviconFile').addEventListener('change',e=>readAssetUpload(e.target,data=>{adminState.branding.favicon=data;$('faviconUrl').value=data;renderBrandingPreviews()}));$('navLogoUrl').addEventListener('input',()=>{adminState.branding.logo=$('navLogoUrl').value.trim();renderBrandingPreviews()});$('faviconUrl').addEventListener('input',()=>{adminState.branding.favicon=$('faviconUrl').value.trim()||'assets/favicon.svg';renderBrandingPreviews()});$('navLogoText').addEventListener('input',()=>{adminState.branding.logoText=$('navLogoText').value;renderBrandingPreviews()});
}
function showSaveToast(){let t=document.querySelector('.admin-toast');if(!t){t=document.createElement('div');t.className='admin-toast';document.body.appendChild(t)}t.textContent='Changes saved';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}

document.addEventListener('DOMContentLoaded',async()=>{try{const access=await ZBSupa.requireRole(['admin','editor','sales','fulfilment']);if(!access.ok){location.replace('account.html?admin=1&return=/admin.html');return}await ZBSupa.hydrateSiteCache({force:true});adminState=getSite()}catch(err){console.error(err);alert('Could not connect Admin to Supabase: '+err.message);return}panelNav();renderSales();renderAnalytics();renderSubs();renderSettings();renderInvoiceLines();renderInvoices();renderEmailLog();bindEvents()});
